/**
 * REQUEST-AUTHORITY HOLDOUT — frozen 2026-08-24, before any operation envelope existed.
 *
 * The fourth frozen corpus in this series and the first about the REQUEST gate. Generated by an
 * independent model from a written seven-rule contract: a closed set of operations, a
 * prohibited-request boundary that a factual half cannot rescue, and the rule that vocabulary
 * alone decides nothing. The generator was shown none of this repository's patterns, none of the
 * IR-107 probe rows, and neither historical advice holdout.
 *
 * `adviceGuardrailHoldout.ts` and `adviceGuardrailHoldout2.ts` remain immutable historical
 * evidence and are not superseded. Their first runs measured 81% and 73.2% false negative for a
 * guardrail built by phrase enumeration, which is why nothing in this unit grows a phrase list.
 *
 * `carriesTradingVocabulary` exists so that over-blocking can be measured directly rather than
 * inferred: a case carrying a trading term without personalized intent is the probe for the
 * defect IR-107 reproduced, where one word turned an unanswerable question into a reported
 * compliance event.
 *
 * sha256 of the labelled set: 0c9099f3698d6f4d7cd8b26c9b1b356a75f45dac6985a69b6188090fb67ecdc1
 */

export type RequestOperation =
  | "CURRENT_OBSERVATION"
  | "OBSERVED_CHANGE"
  | "STORED_MECHANISM"
  | "ATTRIBUTED_REPORTED_OBSERVATION"
  | "DEFINITION"
  | "NONE";

export interface RequestAuthorityCase {
  id: string;
  language: "EN" | "KO";
  query: string;
  /** The operation the request asks for, or NONE when it asks for none. */
  operation: RequestOperation;
  /**
   * ANSWERABLE means the request is well formed and permitted — NOT that any record exists.
   * UNSUPPORTED and PROHIBITED are deliberately distinct: a question the product cannot answer
   * is not an attempted violation, and reporting it as one is itself the defect.
   */
  expected: "ANSWERABLE" | "UNSUPPORTED" | "PROHIBITED" | "AMBIGUOUS";
  /** True when the query contains a trading term, whatever the intent. Measures over-blocking. */
  carriesTradingVocabulary: boolean;
  rationale: string;
}

/** Holdout until something here drives a change; regression evidence from that moment on. */
